insert into public.bills (state, number, year, status, summary, topics) values
  ('PA', 'SB 1384', 2025, 'Introduced', 'Closes the state''s data center incentive to new applicants and ties a new one to matched clean power, jobs and cost coverage.', array['Clean energy supply', 'Incentive reform', 'Community protection']::text[]),
  ('CO', 'SB 102', 2026, 'Failed', 'Would have required long contracts, banned discount rates and required hourly clean power matching and community agreements.', array['Clean energy supply', 'Grid cost protection', 'Grid planning', 'Grid reliability', 'Community protection', 'Water stewardship']::text[]),
  ('FL', 'SB 484', 2026, 'Passed', 'Utilities must set special tariffs so large customers cover their own costs. Keeps local zoning and adds a water permit hearing.', array['Grid cost protection', 'Water stewardship']::text[]),
  ('NJ', 'A 796', 2026, 'Passed', 'Special utility rules for big data centers: an 85% minimum use commitment, financial security and cutbacks ahead of homes.', array['Clean energy supply', 'Grid cost protection', 'Grid planning', 'Grid reliability']::text[]),
  ('TX', 'SB 6', 2025, 'Failed', 'Large users pay to connect, meet financial commitments and can be cut back during grid stress.', array['Grid cost protection', 'Grid planning', 'Grid reliability']::text[]),
  ('IL', 'SB 4016', 2025, 'Introduced', 'Clean supply plans, cost rules, impact assessments and community benefit agreements. Stalled in committee.', array['Clean energy supply', 'Grid cost protection', 'Grid planning', 'Incentive reform', 'Grid reliability', 'Community protection', 'Water stewardship']::text[]),
  ('PA', 'HB 1834', 2025, 'Engrossed', 'Financial security, exit fees, cost causation and rising clean power requirements. Passed the House.', array['Clean energy supply', 'Grid cost protection', 'Grid planning', 'Incentive reform', 'Grid reliability', 'Community protection']::text[]),
  ('MD', 'HB 1532', 2026, 'Passed', 'A separate rate schedule for large users with collateral and exit fees, plus voluntary tiers for new clean energy.', array['Clean energy supply', 'Grid cost protection']::text[]),
  ('DE', 'HB 233', 2025, 'Introduced', 'Ten year service agreements, a separate rate class and cutbacks in grid emergencies.', array['Clean energy supply', 'Grid cost protection']::text[]),
  ('MI', 'HB 5790', 2025, 'Introduced', 'Adds green building and clean energy conditions to an existing tax break, with repayment if missed.', '{}'::text[]),
  ('OH', 'SB 381', 2025, 'Introduced', 'The utility regulator must approve a connection before construction, based on an independent forecast.', array['Grid cost protection', 'Grid planning']::text[]),
  ('SC', 'S 902', 2025, 'Introduced', 'A siting act with decommissioning plans and a commission certificate before building.', array['Grid cost protection', 'Community protection', 'Water stewardship']::text[]),
  ('WA', 'HB 1846', 2021, 'Passed', 'A sales tax break that depends on family wage jobs and a green building certificate, with repayment if missed.', array['Incentive reform']::text[]),
  ('ID', 'HB 911', 2026, 'Passed', 'Regulators approve large new loads before they connect, using a no harm test and financial security.', array['Grid cost protection', 'Grid planning']::text[]),
  ('NC', 'S 1026', 2025, 'Introduced', 'Reviews demand forecasts, requires 20 year contracts and creates a large load tariff. Pending in a Senate committee.', array['Grid cost protection', 'Grid planning']::text[]),
  ('IL', 'HB 5607', 2025, 'Introduced', 'Hourly clean power matching from 20% in 2030 to 100% in 2035, though credits can come from older plants.', array['Clean energy supply']::text[]),
  ('NJ', 'A 4801', 2026, 'Engrossed', 'Large loads post financial security, report their demand and bear backstop power costs.', array['Grid cost protection']::text[]),
  ('PA', 'HB 2246', 2025, 'Engrossed', 'Data centers using over 100,000 gallons of water a day must disclose sources and conservation plans and get a permit.', array['Water stewardship']::text[]),
  ('IN', 'SB 431', 2025, 'Passed', 'Bars new data centers owned by foreign adversaries unless a state study shows they won''t strain the grid.', array['Grid planning']::text[]),
